#!/usr/bin/env python3
"""Generate the Kotlin contract (DTOs + operation registry) from the server's OpenAPI snapshot (CUS-009).

Usage: python3 scripts/api_sync.py [--check] [--spec PATH] [--out DIR]
  default spec: ../WAB-Server/docs/api/openapi.customer.json (the contract, INTEGRATION.md §3)
  default out:  core/data/src/commonMain/kotlin/com/acme/shop/core/data/contract/generated
--check exits 1 when any generated file differs from what the spec produces (CI and the local gate run it).
Generated files are excluded from the 300-line and hardcoded-value policies (config/policy.json).
"""
from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from contract_fixtures import envelope_json, load_captured, render_captured_ids, render_decoders  # noqa: E402

PROJECT_ROOT = Path(__file__).resolve().parents[1]
DEFAULT_SPEC = PROJECT_ROOT / "docs" / "api" / "openapi.json"
DEFAULT_OUT = PROJECT_ROOT / "core/data/src/commonMain/kotlin/com/acme/shop/core/data/contract/generated"
DEFAULT_TEST_OUT = PROJECT_ROOT / "core/data/src/commonTest/kotlin/com/acme/shop/core/data/contract/generated"
# Real responses (capture_remote_fixtures.py, CUS-060) replace the schema-derived fixture of their operation.
DEFAULT_CAPTURED = PROJECT_ROOT / "core/data/fixtures/remote"
DECODERS_FILE = "ContractDecoders.kt"
PACKAGE = "com.acme.shop.core.data.contract.generated"
NAMESPACE_PREFIX = "/app/v1"
METHODS = ("get", "post", "put", "patch", "delete")
SUCCESS_CODES = ("200", "201")
# Phone samples so the mock login flow validates like Jordan (PRD S11); no backslashes, they survive two escapings.
SAMPLE_DIAL_CODE = "+962"
SAMPLE_PHONE_REGEX = "^7[789][0-9]{7}$"
SAMPLE_COUNTRY_CODES = ("JO", "SA", "AE")
# OTP policy samples match the backend defaults (PRD S13: 6 digits, 60 s resend) so the mock flow behaves like production.
SAMPLE_INTEGER_HINTS = {"otplength": 6, "resendafterseconds": 60, "expiresinseconds": 300}
# Flags that must be true for the mock flow to proceed (a pre-check that is never allowed would block every screen).
SAMPLE_TRUE_FLAGS = ("allowed", "available")
# Number samples the UI branches on (counts shown as "N items").
SAMPLE_NUMBER_HINTS = {"branchcount": 3}
# Flags true only for the first list item (one primary entry, listed first).
SAMPLE_FIRST_ITEM_FLAGS = ("ismain",)
# Fixed strings for fields whose value the UI parses (hours "HH:mm", banner action codes).
HEADER = "// GENERATED by scripts/api_sync.py from {name}. Do not edit; run ./gradlew apiSync.\n// sha256 {sha}\n"
KOTLIN_KEYWORDS = {"object", "class", "val", "var", "fun", "in", "is", "as", "when", "if", "else", "for", "while", "do", "return", "package", "import", "interface", "typealias", "this", "super", "null", "true", "false"}


def pascal(text: str) -> str:
    return "".join(part[:1].upper() + part[1:] for part in re.split(r"[^A-Za-z0-9]+", text) if part)


def operation_id(method: str, path: str) -> str:
    rest = path[len(NAMESPACE_PREFIX):] if path.startswith(NAMESPACE_PREFIX) else path
    segments = []
    for segment in rest.strip("/").split("/"):
        if not segment:
            continue
        segments.append("By" + pascal(segment[1:-1]) if segment.startswith("{") else pascal(segment))
    return method.capitalize() + "".join(segments)


class Renderer:
    def __init__(self, spec: dict):
        self.spec = spec
        self.classes: dict[str, list[str]] = {}  # file key -> rendered classes
        self.data_types: dict[str, str | None] = {}  # operation id -> Kotlin type of `data`

    # ---- type resolution --------------------------------------------------
    def kotlin_type(self, schema: dict | None, name: str, file_key: str) -> str:
        if not schema:
            return "JsonElement"
        if "$ref" in schema:
            return schema["$ref"].rsplit("/", 1)[-1]
        if any(k in schema for k in ("oneOf", "anyOf", "allOf")):
            return "JsonElement"
        kind = schema.get("type")
        if isinstance(kind, list):
            kind = next((k for k in kind if k != "null"), "null")
        if kind == "object":
            props = schema.get("properties")
            if props:
                self.render_class(name, schema, file_key)
                return name
            extra = schema.get("additionalProperties")
            return "Map<String, JsonElement>" if extra else "JsonObject"
        if kind == "array":
            return f"List<{self.kotlin_type(schema.get('items'), name + 'Item', file_key)}>"
        return {"string": "String", "integer": "Int", "number": "Double", "boolean": "Boolean"}.get(kind, "JsonElement")

    @staticmethod
    def nullable(schema: dict | None, required: bool) -> bool:
        if not schema:
            return True
        kind = schema.get("type")
        return (isinstance(kind, list) and "null" in kind) or not required

    def render_class(self, name: str, schema: dict, file_key: str) -> None:
        required = set(schema.get("required", []))
        lines = [f"@Serializable\ndata class {name}("]
        for prop, sub in schema.get("properties", {}).items():
            kotlin = self.kotlin_type(sub, name + pascal(prop), file_key)
            optional = self.nullable(sub, prop in required)
            field = f"`{prop}`" if prop in KOTLIN_KEYWORDS or not re.match(r"^[A-Za-z_][A-Za-z0-9_]*$", prop) else prop
            doc = f"    /** One of: {', '.join(map(str, sub['enum']))}. */\n" if isinstance(sub, dict) and sub.get("enum") else ""
            serial = f'    @SerialName("{prop}")\n' if field != prop else ""
            lines.append(f"{doc}{serial}    val {field}: {kotlin}{'? = null' if optional else ''},")
        lines.append(")")
        self.classes.setdefault(file_key, []).append("\n".join(lines))

    # ---- files --------------------------------------------------------------
    def render(self, spec_name: str, sha: str) -> dict[str, str]:
        operations: list[str] = []
        for schema_name, schema in self.spec.get("components", {}).get("schemas", {}).items():
            if schema.get("type") == "object" and schema.get("properties"):
                self.render_class(schema_name, schema, "Components")
        for path, methods in self.spec.get("paths", {}).items():
            for method, op in methods.items():
                if method not in METHODS:
                    continue
                op_id = operation_id(method, path)
                tag = (op.get("tags") or ["Common"])[0]
                file_key = pascal(tag) + "Dtos"
                body_schema = op.get("requestBody", {}).get("content", {}).get("application/json", {}).get("schema")
                body_type = self.kotlin_type(body_schema, op_id + "Body", file_key) if body_schema else None
                data_type = None
                for code in SUCCESS_CODES:
                    response = op.get("responses", {}).get(code, {}).get("content", {}).get("application/json", {}).get("schema")
                    if response and "properties" in response and "data" in response["properties"]:
                        data_type = self.kotlin_type(response["properties"]["data"], op_id + "Data", file_key)
                        break
                self.data_types[op_id] = data_type
                query = [p["name"] for p in op.get("parameters", []) if p.get("in") == "query"]
                path_params = [p["name"] for p in op.get("parameters", []) if p.get("in") == "path"]
                operations.append(
                    f'    val {op_id[:1].lower() + op_id[1:]} = Operation(\n'
                    f'        method = Method.{method.upper()},\n        path = "{path}",\n        tag = "{tag}",\n'
                    f'        pathParams = listOf({", ".join(chr(34) + p + chr(34) for p in path_params)}),\n'
                    f'        queryParams = listOf({", ".join(chr(34) + q + chr(34) for q in query)}),\n'
                    f'        bodyType = {chr(34) + body_type + chr(34) if body_type else "null"},\n'
                    f'        dataType = {chr(34) + data_type + chr(34) if data_type else "null"},\n    )'
                )
        files: dict[str, str] = {}
        head = HEADER.format(name=spec_name, sha=sha)
        imports = "import kotlinx.serialization.SerialName\nimport kotlinx.serialization.Serializable\nimport kotlinx.serialization.json.JsonElement\nimport kotlinx.serialization.json.JsonObject\n"
        for file_key, classes in sorted(self.classes.items()):
            files[f"{file_key}.kt"] = f"{head}package {PACKAGE}\n\n{imports}\n" + "\n\n".join(classes) + "\n"
        files["Operations.kt"] = (
            f"{head}package {PACKAGE}\n\nenum class Method {{ GET, POST, PUT, PATCH, DELETE }}\n\n"
            "/** One entry per operation of the contract; repositories build requests from it, never from literals. */\n"
            "data class Operation(\n    val method: Method,\n    val path: String,\n    val tag: String,\n"
            "    val pathParams: List<String>,\n    val queryParams: List<String>,\n    val bodyType: String?,\n    val dataType: String?,\n)\n\n"
            "object CustomerOperations {\n" + "\n\n".join(operations) + "\n\n    val all: List<Operation> = listOf(\n"
            + "".join(f"        {operation_id(m, p)[:1].lower() + operation_id(m, p)[1:]},\n" for p, ms in self.spec.get("paths", {}).items() for m in ms if m in METHODS)
            + "    )\n}\n"
        )
        return files


TEXT_FIELD_HINTS = ("name", "description", "title", "body", "message", "comment", "text", "address", "bio", "reason", "label")
TEXT_MARKER = "__TEXT__"
SAMPLE_ITEMS = 3
SAMPLE_DATE = "2026-10-18T10:00:00.000Z"
SAMPLE_STRING_HINTS = {"open": "08:00", "close": "16:00", "actiontype": "NONE", "min": "5", "max": "100", "createdat": SAMPLE_DATE, "start": "09:00", "end": "17:00", "day": "SAT", "appointmentstart": SAMPLE_DATE, "appointmentend": SAMPLE_DATE, "respondby": SAMPLE_DATE, "referencenumber": "WAB-1001", "status": "APPROVED", "paymentstatus": "DEPOSIT_PAID", "paymentmethod": "DEPOSIT", "price": "15", "total": "30"}
SAMPLE_URL = "https://example.invalid/sample.jpg"
SAMPLE_ID_PREFIX = "id-"


def sample_value(schema: dict | None, field: str, components: dict, depth: int = 0, index: int = 0):
    """A realistic-looking value for a schema node; text fields carry a marker the mock localizes per language."""
    if not schema or depth > 12:
        return None
    if "$ref" in schema:
        return sample_value(components.get(schema["$ref"].rsplit("/", 1)[-1]), field, components, depth + 1, index)
    kind = schema.get("type")
    if isinstance(kind, list):
        kind = next((k for k in kind if k != "null"), "null")
    if "enum" in schema:
        return schema["enum"][0]
    if kind == "object":
        return {prop: sample_value(sub, prop, components, depth + 1, index) for prop, sub in schema.get("properties", {}).items()} if schema.get("properties") else {}
    if kind == "array":
        # Items differ in their ids / codes so list keys stay unique in the UI (LazyColumn keys).
        return [sample_value(schema.get("items"), field, components, depth + 1, i) for i in range(SAMPLE_ITEMS)]
    if kind == "string":
        lower = field.lower()
        if schema.get("format") == "date-time":
            return SAMPLE_DATE
        if lower in SAMPLE_STRING_HINTS:
            return SAMPLE_STRING_HINTS[lower]
        if lower == "dialcode":
            return SAMPLE_DIAL_CODE
        if lower.endswith("regex"):
            return SAMPLE_PHONE_REGEX
        if lower in ("code", "countrycode"):
            return SAMPLE_COUNTRY_CODES[index % len(SAMPLE_COUNTRY_CODES)]
        if lower.endswith("url") or lower.endswith("urls"):
            return SAMPLE_URL
        if lower == "id" or lower.endswith("id"):
            return f"{SAMPLE_ID_PREFIX}{index + 1}"
        return TEXT_MARKER if any(h in lower for h in TEXT_FIELD_HINTS) else field
    if kind == "integer":
        return SAMPLE_INTEGER_HINTS.get(field.lower(), 1)
    if kind == "number":
        return SAMPLE_NUMBER_HINTS.get(field.lower(), 1.5)
    if kind == "boolean":
        return field.lower() in SAMPLE_TRUE_FLAGS or (field.lower() in SAMPLE_FIRST_ITEM_FLAGS and index == 0)
    return None


def render_fixtures(spec: dict, head: str, captured: dict[str, dict] | None = None) -> str:
    components = spec.get("components", {}).get("schemas", {})
    entries, used = [], []
    for path, methods in spec.get("paths", {}).items():
        for method, op in methods.items():
            if method not in METHODS:
                continue
            op_id = operation_id(method, path)
            data = None
            for code in SUCCESS_CODES:
                response = op.get("responses", {}).get(code, {}).get("content", {}).get("application/json", {}).get("schema")
                if response and "properties" in response:
                    data = sample_value(response["properties"].get("data"), "data", components)
                    break
            real = (captured or {}).get(op_id)
            used += [op_id] if real else []
            body = envelope_json(real) if real else json.dumps({"success": True, "message": "", "data": data}, ensure_ascii=False)
            escaped = body.replace("\\", "\\\\").replace('"', '\\"').replace("$", "\\$")
            entries.append(f'    "{op_id}" to "{escaped}",')
    return (
        f"{head}package {PACKAGE}\n\n"
        "/** Success-envelope JSON per operation id, derived from the response schema; `MockTransport` serves and localizes it. */\n"
        "object MockFixtures {\n    const val TEXT_MARKER = \"" + TEXT_MARKER + "\"\n\n    val byOperationId: Map<String, String> = mapOf(\n"
        + "\n".join(entries) + "\n    )\n\n" + render_captured_ids(used) + "}\n"
    )


def generate(spec_path: Path, captured_dir: Path | None = None) -> tuple[dict[str, str], str, dict[str, str]]:
    """(main source files, spec sha, commonTest files)."""
    text = spec_path.read_text(encoding="utf-8")
    sha = hashlib.sha256(text.encode("utf-8")).hexdigest()
    spec = json.loads(text)
    renderer = Renderer(spec)
    files = renderer.render(spec_path.name, sha)
    head = HEADER.format(name=spec_path.name, sha=sha)
    files["MockFixtures.kt"] = render_fixtures(spec, head, load_captured(captured_dir))
    files["openapi.snapshot.json"] = text
    return files, sha, {DECODERS_FILE: render_decoders(head, PACKAGE, renderer.data_types)}


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--spec", default=str(DEFAULT_SPEC))
    parser.add_argument("--out", default=str(DEFAULT_OUT))
    parser.add_argument("--test-out", default=str(DEFAULT_TEST_OUT))
    parser.add_argument("--captured", default=str(DEFAULT_CAPTURED))
    args = parser.parse_args(argv)
    spec_path = Path(args.spec)
    if not spec_path.is_file():
        print(f"api_sync: spec not found: {spec_path}")
        return 1
    files, sha, test_files = generate(spec_path, Path(args.captured))
    targets = ((Path(args.out), files), (Path(args.test_out), test_files))
    stale = [(out, n) for out, fs in targets for n, text in fs.items() if not (out / n).is_file() or (out / n).read_text(encoding="utf-8") != text]
    extra = [(out, p.name) for out, fs in targets if out.is_dir() for p in out.glob("*") if p.is_file() and p.name not in fs]
    if args.check:
        for _, name in stale + extra:
            print(f"api_sync --check: {name} is stale; run ./gradlew apiSync")
        print("api_sync: ok" if not stale and not extra else f"api_sync: FAILED, {len(stale) + len(extra)} file(s)")
        return 1 if stale or extra else 0
    for out, name in extra:
        (out / name).unlink()
    for out, fs in targets:
        out.mkdir(parents=True, exist_ok=True)
        for name, text in fs.items():
            (out / name).write_text(text, encoding="utf-8")
    print(f"api_sync: wrote {len(files) + len(test_files)} files from {spec_path.name} ({sha[:12]})")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
